/**
 * Verifies the Python statistics engine against values worked out by hand.
 *
 * A statistics feature that silently returns the wrong p-value is worse than
 * one that does not exist, so every case here has a known answer rather than a
 * golden file generated by the code under test.
 */

import { runBiostatistics, resetPythonCache } from "../src/lib/biostat-python";

let passed = 0;
let failed = 0;

function check(name: string, condition: boolean, detail = ""): void {
  if (condition) {
    passed++;
    console.log(`  [PASS] ${name}${detail ? ` - ${detail}` : ""}`);
  } else {
    failed++;
    console.log(`  [FAIL] ${name}${detail ? ` - ${detail}` : ""}`);
  }
}

function near(actual: unknown, expected: number, tolerance = 0.001): boolean {
  return typeof actual === "number" && Math.abs(actual - expected) <= tolerance;
}

/** Right-tailed t-test on two groups of six, means 12.42 and 15.38. */
async function tTestCase(): Promise<void> {
  const result = await runBiostatistics({
    columns: ["group", "score"],
    rows: [
      ["A", "12.1"], ["A", "12.8"], ["A", "11.9"], ["A", "13.2"], ["A", "12.5"], ["A", "12.0"],
      ["B", "15.3"], ["B", "14.8"], ["B", "16.1"], ["B", "15.7"], ["B", "14.9"], ["B", "15.5"],
    ],
  });
  const test = result.tests?.[0];
  check("t-test: engine ran", result.ran, result.ran ? "" : result.error ?? "");
  check("t-test: a test was chosen", Boolean(test), test?.test ?? "none");
  check("t-test: mean of group A", near(test?.mean_a, 12.4167, 0.01), `${test?.mean_a}`);
  check("t-test: mean of group B", near(test?.mean_b, 15.3833, 0.01), `${test?.mean_b}`);
  check("t-test: p is significant", test?.significant === true, `p=${test?.p}`);
  check("t-test: effect size is large", test?.effect_label === "large", `d=${(test?.effect as { cohens_d?: number })?.cohens_d}`);
}

/** Three groups, means 10.2 / 14.0 / 17.8, each n=6. Should be significant. */
async function anovaCase(): Promise<void> {
  const rows: string[][] = [];
  const means: Record<string, number> = { Low: 10.2, Mid: 14.0, High: 17.8 };
  for (const [arm, mean] of Object.entries(means)) {
    for (let i = 0; i < 6; i++) {
      rows.push([arm, (mean + (i - 2.5) * 0.4).toFixed(2)]);
    }
  }
  const result = await runBiostatistics({ columns: ["arm", "value"], rows });
  const test = result.tests?.[0];
  check("anova: engine ran", result.ran);
  check("anova: ANOVA was chosen", String(test?.test ?? "").includes("ANOVA"), test?.test ?? "none");
  check("anova: p is significant", test?.significant === true, `p=${test?.p}`);
  check("anova: degrees of freedom", test?.df_between === 2 && test?.df_within === 15, `df=${test?.df_between}/${test?.df_within}`);
  check("anova: eta squared reported", typeof test?.eta_squared === "number", `eta2=${test?.eta_squared}`);
}

/** Deterministic linear relationship: correlation should be ~0.99. */
async function regressionCase(): Promise<void> {
  const rows: string[][] = [];
  for (let i = 1; i <= 24; i++) {
    const age = 20 + i;
    const cholesterol = 4.2 + age * 0.35 + ((i % 5) * 0.22) - 0.1;
    rows.push([String(age), cholesterol.toFixed(3)]);
  }
  const result = await runBiostatistics({ columns: ["age", "cholesterol"], rows });
  const correlation = result.tests?.find((t) => t.pearson_r !== undefined);
  const regression = result.tests?.find((t) => t.r_squared !== undefined);
  check("regression: engine ran", result.ran);
  check("correlation: strong positive r", near(correlation?.pearson_r, 0.9925, 0.01), `r=${correlation?.pearson_r}`);
  check("regression: age predicts cholesterol", regression?.predictor === "age", `predictor=${regression?.predictor}`);
  check("regression: R squared is high", near(regression?.r_squared, 0.985, 0.01), `r2=${regression?.r_squared}`);
  check("regression: equation present", String(regression?.equation ?? "").includes("cholesterol ="), String(regression?.equation ?? ""));
}

/** 2x2 diagnostic table. Hand-computed values are pinned below. */
async function diagnosticCase(): Promise<void> {
  const result = await runBiostatistics({
    columns: ["dummy"],
    rows: [["x"]],
    confusion: { tp: 45, fn: 5, tn: 88, fp: 12 },
  });
  const test = result.tests?.[0];
  check("diagnostic: engine ran", result.ran);
  check("diagnostic: sensitivity = 45/50", near(test?.sensitivity, 0.9, 0.0001), `${test?.sensitivity}`);
  check("diagnostic: specificity = 88/100", near(test?.specificity, 0.88, 0.0001), `${test?.specificity}`);
  check("diagnostic: ppv = 45/133", near(test?.ppv, 45 / 133, 0.0001), `${test?.ppv}`);
  check("diagnostic: npv = 88/93", near(test?.npv, 88 / 93, 0.0001), `${test?.npv}`);
  check("diagnostic: accuracy", near(test?.accuracy, 133 / 150, 0.0001), `${test?.accuracy}`);
  check("diagnostic: odds ratio = 66", near(test?.odds_ratio, 66, 0.01), `OR=${test?.odds_ratio}`);
}

async function edgeCases(): Promise<void> {
  const empty = await runBiostatistics({ columns: [], rows: [] });
  check("edge: empty table is rejected, not crashed", empty.ok === false && empty.ran === false, empty.error ?? "");

  const messy = await runBiostatistics({
    columns: ["a", "b"],
    rows: [["x", ""], ["y", "abc"], ["z", "NaN"], ["w", "3"]],
  });
  check("edge: unparseable cells do not throw", messy.ran === true || messy.ok === false);
  if (messy.ran) {
    // Only one of four cells parsed, so the column is text, not a measurement.
    // Treating it as numeric would compute a mean of 3 and call it a dataset.
    check("edge: a mostly-text column is not treated as numeric", messy.numericColumns?.includes("b") !== true, `numeric=${messy.numericColumns}`);
  }

  // A column that is genuinely mostly numbers must still be found, or the rule
  // above would be hiding real data.
  const mixed = await runBiostatistics({
    columns: ["label", "value"],
    rows: [["a", "1"], ["b", "2"], ["c", "3"], ["d", "4"], ["e", ""]],
  });
  check("edge: a mostly-numeric column is still found", mixed.numericColumns?.includes("value") === true, `numeric=${mixed.numericColumns}`);

  const thousands = await runBiostatistics({
    columns: ["label", "value"],
    rows: [["a", "1,200"], ["b", "3,400"], ["c", "5,600"], ["d", "7,800"]],
  });
  check("edge: thousands separators are parsed", thousands.descriptives?.value?.mean === 4500, `mean=${thousands.descriptives?.value?.mean}`);

  const single = await runBiostatistics({ columns: ["a", "b"], rows: [["x", "1"]] });
  check("edge: one row does not throw", single.ran === true || single.ok === false);
}

/** A 2x2 with small expected counts must warn rather than quietly report. */
async function assumptionWarning(): Promise<void> {
  const rows: string[][] = [];
  for (let i = 0; i < 8; i++) rows.push(["Smoker", "Yes"]);
  for (let i = 0; i < 8; i++) rows.push(["Non", "No"]);
  const result = await runBiostatistics({ columns: ["smoker", "disease"], rows });
  const warned = (result.warnings ?? []).some((w) => /expected count/i.test(w));
  check("assumptions: small expected count is flagged", warned, (result.warnings ?? [])[0] ?? "no warning");
}

async function main(): Promise<void> {
  console.log("PYTHON STATISTICS ENGINE CHECKS\n");
  resetPythonCache();

  await tTestCase();
  await anovaCase();
  await regressionCase();
  await diagnosticCase();
  await edgeCases();
  await assumptionWarning();

  console.log(`\n${failed === 0 ? "STATISTICS ENGINE CHECKS PASSED" : `${failed} CHECK(S) FAILED`}`);
  if (failed > 0) process.exit(1);
}

main().catch((error) => {
  console.error("Statistics engine check crashed:", error);
  process.exit(1);
});
